'use client';

import { useState, useCallback, type ReactNode } from 'react';
import { clsx } from 'clsx';
import { twMerge } from 'tailwind-merge';

// ============================================
// Types
// ============================================

export type CodeLanguage = 'swift' | 'kotlin' | 'javascript' | 'typescript' | 'json' | 'bash' | 'java' | 'dart' | 'react-native';

export interface CodeSnippet {
  language: CodeLanguage;
  label?: string;
  code: string;
}

export interface CodeBlockProps {
  /** Single code string or multiple snippets for tabs */
  code: string | CodeSnippet[];
  /** Language for syntax highlighting (when code is string) */
  language?: CodeLanguage;
  /** Show line numbers */
  showLineNumbers?: boolean;
  /** Title/filename to display */
  title?: string;
  /** Show copy button */
  showCopy?: boolean;
  /** Maximum height before scrolling */
  maxHeight?: string;
  /** Additional CSS classes */
  className?: string;
}

// ============================================
// Language Configuration
// ============================================

const languageConfig: Record<CodeLanguage, { label: string; icon: ReactNode }> = {
  swift: {
    label: 'Swift',
    icon: <SwiftIcon />,
  },
  kotlin: {
    label: 'Kotlin',
    icon: <KotlinIcon />,
  },
  java: {
    label: 'Java',
    icon: <JavaIcon />,
  },
  javascript: {
    label: 'JavaScript',
    icon: <JSIcon />,
  },
  typescript: {
    label: 'TypeScript',
    icon: <TSIcon />,
  },
  'react-native': {
    label: 'React Native',
    icon: <ReactIcon />,
  },
  dart: {
    label: 'Flutter',
    icon: <DartIcon />,
  },
  json: {
    label: 'JSON',
    icon: <JSONIcon />,
  },
  bash: {
    label: 'Terminal',
    icon: <TerminalIcon />,
  },
};

// ============================================
// Syntax Highlighting (Basic)
// ============================================

function highlightCode(code: string, language: CodeLanguage): string {
  // Keywords by language
  const keywords: Record<string, string[]> = {
    swift: ['import', 'func', 'let', 'var', 'class', 'struct', 'enum', 'if', 'else', 'guard', 'return', 'try', 'catch', 'throw', 'await', 'async', 'private', 'public', 'static', 'self', 'Self', 'nil', 'true', 'false', 'override', 'init', 'deinit', 'extension', 'protocol', 'where', 'case', 'default', 'switch', 'for', 'in', 'while', 'do', 'break', 'continue'],
    kotlin: ['import', 'fun', 'val', 'var', 'class', 'object', 'interface', 'if', 'else', 'when', 'return', 'try', 'catch', 'throw', 'suspend', 'private', 'public', 'internal', 'override', 'companion', 'data', 'sealed', 'enum', 'null', 'true', 'false', 'this', 'super', 'is', 'as', 'in', 'for', 'while', 'do', 'break', 'continue'],
    java: ['import', 'public', 'private', 'protected', 'class', 'interface', 'extends', 'implements', 'static', 'final', 'void', 'return', 'if', 'else', 'try', 'catch', 'throw', 'throws', 'new', 'this', 'super', 'null', 'true', 'false', 'for', 'while', 'do', 'break', 'continue', 'switch', 'case', 'default'],
    javascript: ['import', 'export', 'from', 'const', 'let', 'var', 'function', 'class', 'if', 'else', 'return', 'try', 'catch', 'throw', 'async', 'await', 'new', 'this', 'null', 'undefined', 'true', 'false', 'for', 'while', 'do', 'break', 'continue', 'switch', 'case', 'default', 'typeof', 'instanceof'],
    typescript: ['import', 'export', 'from', 'const', 'let', 'var', 'function', 'class', 'interface', 'type', 'if', 'else', 'return', 'try', 'catch', 'throw', 'async', 'await', 'new', 'this', 'null', 'undefined', 'true', 'false', 'for', 'while', 'do', 'break', 'continue', 'switch', 'case', 'default', 'typeof', 'instanceof', 'as', 'readonly', 'private', 'public', 'protected'],
    'react-native': ['import', 'export', 'from', 'const', 'let', 'var', 'function', 'class', 'if', 'else', 'return', 'try', 'catch', 'throw', 'async', 'await', 'new', 'this', 'null', 'undefined', 'true', 'false'],
    dart: ['import', 'class', 'extends', 'implements', 'with', 'if', 'else', 'return', 'try', 'catch', 'throw', 'async', 'await', 'final', 'const', 'var', 'void', 'null', 'true', 'false', 'this', 'super', 'new', 'static', 'override', 'required'],
    json: [],
    bash: ['echo', 'cd', 'ls', 'mkdir', 'rm', 'cp', 'mv', 'cat', 'grep', 'sudo', 'npm', 'npx', 'yarn', 'pod', 'swift', 'xcodebuild'],
  };

  let highlighted = escapeHtml(code);

  // Highlight strings (must be done first to avoid conflicts)
  highlighted = highlighted.replace(
    /(&quot;[^&]*&quot;|&#39;[^&]*&#39;|`[^`]*`)/g,
    '<span class="code-string">$1</span>'
  );

  // Highlight comments
  highlighted = highlighted.replace(
    /(\/\/.*$|\/\*[\s\S]*?\*\/|#.*$)/gm,
    '<span class="code-comment">$1</span>'
  );

  // Highlight keywords
  const langKeywords = keywords[language] || [];
  langKeywords.forEach(keyword => {
    const regex = new RegExp(`\\b(${keyword})\\b`, 'g');
    highlighted = highlighted.replace(
      regex,
      '<span class="code-keyword">$1</span>'
    );
  });

  // Highlight numbers
  highlighted = highlighted.replace(
    /\b(\d+\.?\d*)\b/g,
    '<span class="code-number">$1</span>'
  );

  // Highlight function calls
  highlighted = highlighted.replace(
    /\b([a-zA-Z_][a-zA-Z0-9_]*)\s*\(/g,
    '<span class="code-function">$1</span>('
  );

  return highlighted;
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// ============================================
// Copy Button
// ============================================

function CopyButton({ code }: { code: string }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy:', err);
    }
  }, [code]);

  return (
    <button
      onClick={handleCopy}
      className={clsx(
        'p-1.5 rounded-md',
        'text-gray-400 hover:text-gray-300',
        'hover:bg-gray-700/50',
        'transition-colors duration-150',
        'focus:outline-none focus:ring-2 focus:ring-violet-500/50'
      )}
      aria-label={copied ? 'Copied!' : 'Copy code'}
    >
      {copied ? <CheckIcon /> : <CopyIcon />}
    </button>
  );
}

// ============================================
// Code Content
// ============================================

function CodeContent({
  code,
  language,
  showLineNumbers,
  maxHeight,
}: {
  code: string;
  language: CodeLanguage;
  showLineNumbers: boolean;
  maxHeight?: string;
}) {
  const highlighted = highlightCode(code, language);
  const highlightedLines = highlighted.split('\n');

  return (
    <div
      className={clsx(
        'overflow-auto',
        'scrollbar-thin scrollbar-thumb-gray-600 scrollbar-track-transparent'
      )}
      style={{ maxHeight }}
    >
      <pre className="p-4 text-sm leading-relaxed">
        <code className="font-mono">
          {highlightedLines.map((line, index) => (
            <div key={index} className="flex">
              {showLineNumbers && (
                <span className="select-none text-gray-500 w-8 flex-shrink-0 text-right pr-4">
                  {index + 1}
                </span>
              )}
              <span
                className="flex-1"
                dangerouslySetInnerHTML={{ __html: line || '&nbsp;' }}
              />
            </div>
          ))}
        </code>
      </pre>
    </div>
  );
}

// ============================================
// Main Component
// ============================================

/**
 * CodeBlock Component
 *
 * A syntax-highlighted code block with optional language tabs.
 * Designed for SDK documentation showing Swift/Kotlin/JS examples.
 *
 * @example
 * // Single language
 * <CodeBlock
 *   language="swift"
 *   code={`let adapty = Adapty.shared`}
 * />
 *
 * @example
 * // Multiple languages with tabs
 * <CodeBlock
 *   code={[
 *     { language: 'swift', code: 'Adapty.activate("key")' },
 *     { language: 'kotlin', code: 'Adapty.activate("key")' },
 *   ]}
 * />
 */
export default function CodeBlock({
  code,
  language = 'typescript',
  showLineNumbers = false,
  title,
  showCopy = true,
  maxHeight = '400px',
  className,
}: CodeBlockProps) {
  // Handle multi-language tabs
  const isMultiLanguage = Array.isArray(code);
  const snippets = isMultiLanguage ? code : [{ language, code }];
  const [activeLanguage, setActiveLanguage] = useState(snippets[0].language);

  const activeSnippet = snippets.find(s => s.language === activeLanguage) || snippets[0];

  return (
    <div
      className={twMerge(
        clsx(
          'rounded-xl overflow-hidden',
          'bg-[#1e1e2e]', // Dark background
          'border border-gray-800',
          'shadow-lg'
        ),
        className
      )}
    >
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-2 bg-[#181825] border-b border-gray-800">
        <div className="flex items-center gap-3">
          {/* Window controls */}
          <div className="flex gap-1.5">
            <span className="w-3 h-3 rounded-full bg-red-500/80" />
            <span className="w-3 h-3 rounded-full bg-yellow-500/80" />
            <span className="w-3 h-3 rounded-full bg-green-500/80" />
          </div>

          {/* Title or language tabs */}
          {title ? (
            <span className="text-sm text-gray-400 font-mono">{title}</span>
          ) : isMultiLanguage ? (
            <div className="flex gap-1">
              {snippets.map((snippet) => {
                const config = languageConfig[snippet.language];
                const isActive = snippet.language === activeLanguage;
                return (
                  <button
                    key={snippet.language}
                    onClick={() => setActiveLanguage(snippet.language)}
                    className={clsx(
                      'flex items-center gap-1.5 px-3 py-1 rounded-md text-sm',
                      'transition-colors duration-150',
                      isActive
                        ? 'bg-gray-700/50 text-white'
                        : 'text-gray-400 hover:text-gray-300 hover:bg-gray-700/30'
                    )}
                  >
                    <span className="w-4 h-4">{config.icon}</span>
                    <span>{snippet.label || config.label}</span>
                  </button>
                );
              })}
            </div>
          ) : (
            <div className="flex items-center gap-1.5 text-gray-400 text-sm">
              <span className="w-4 h-4">{languageConfig[language].icon}</span>
              <span>{languageConfig[language].label}</span>
            </div>
          )}
        </div>

        {/* Copy button */}
        {showCopy && <CopyButton code={activeSnippet.code} />}
      </div>

      {/* Code content */}
      <CodeContent
        code={activeSnippet.code}
        language={activeSnippet.language}
        showLineNumbers={showLineNumbers}
        maxHeight={maxHeight}
      />

      {/* Syntax highlighting styles */}
      <style jsx global>{`
        .code-keyword {
          color: #cba6f7; /* Purple */
        }
        .code-string {
          color: #a6e3a1; /* Green */
        }
        .code-comment {
          color: #6c7086; /* Gray */
          font-style: italic;
        }
        .code-number {
          color: #fab387; /* Orange */
        }
        .code-function {
          color: #89b4fa; /* Blue */
        }
      `}</style>
    </div>
  );
}

